/// <summary>
/// PaffH 13.12.24
/// </summary>
/// <param name = "append">boolean</param>
public void create(boolean append)
{
    next create(append);
    this.nDX_enableButtonProdIdent();
}

/// <summary>
/// PaffH 13.12.24
/// last modified: PaffH 18.12.24
/// </summary>
/// <returns>int</returns>
int active()
{
    ProdParmRelease prodParmRelease = this.cursor();
    prodParmRelease.NDXPrintProdProdIdent = NDXProdTableProdIdentProdPool::checkPrintProdIdentQRCodesForProdPool(prodParmRelease);
    prodParmRelease.update();

    int ret = next active();
    this.nDX_enableButtonProdIdent();

    return ret;
}

/// <summary>
/// PaffH 13.12.24
/// </summary>
public void nDX_enableButtonProdIdent()
{
    ProdParmRelease prodParmRelease = this.cursor();
    FormRun formRun = this.formRun();
    FormControl nDXSetupButtonProdIdentCtrl = formRun.design().controlName(formControlStr(ProdParmRelease, NDXSetupButtonProdIdent));

    if (nDXSetupButtonProdIdentCtrl)
    {
        nDXSetupButtonProdIdentCtrl.enabled(prodParmRelease.NDXPrintProdProdIdent == NoYes::Yes);
    }
}
